{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "요청을 요구사항으로 구체화하면서 포함할 범위와 제외할 범위를 판단할 수 있는지 확인한다. 개발 담당 팀원과 범위를 조정한 경험에서 요구사항의 경계를 정한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰하고 개발 담당 팀원과 범위를 조정했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성했다.",
          "action": "요구사항에 담을 범위를 정한 근거를 실제로 검토한 요청과 연결해 설명한다.",
          "result": "설명한 근거가 어떤 요구사항을 포함하거나 제외하는 판단으로 이어졌는지 설명한다."
        },
        "expectedEvidence": [
          "요구사항에 담을 범위를 정한 구체적인 근거",
          "그 근거를 뒷받침한 인터뷰 내용이나 범위 조정 당시의 제약",
          "해당 근거와 포함하거나 제외한 요구사항 사이의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨을 때, 요구사항에 담을 범위를 정한 근거는 무엇이었나요?",
      "answerTip": "구체적인 경험을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "범위를 정한 근거를 실제 요청이나 당시의 제약에 연결해 구체적으로 설명한다.",
            "제시한 근거로 요구사항을 포함하거나 제외한 판단을 일관되게 설명해 범위의 경계가 분명하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "범위를 정한 근거를 제시하지만 중요도나 일정 같은 일반적인 설명에 머문다.",
            "근거와 포함하거나 제외한 요구사항의 연결을 설명하지만 범위의 경계가 일부 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "범위를 정한 근거 없이 요구사항 정의서를 작성했다는 사실이나 문서 항목만 나열한다.",
            "범위 판단과 무관한 협업 태도나 도구 사용 이야기로 답해 요구사항의 경계를 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황에서도 사용자가 다음 행동을 알 수 있도록 화면 흐름을 구체적으로 설계할 수 있는지 확인한다. 화면설계서를 작성한 경험에서 예외 상황의 흐름을 설계한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "기획 담당으로 Figma를 사용해 화면설계서를 작성했다.",
          "action": "실제로 설계한 예외 상황의 화면 흐름을 짚어 그 흐름을 택한 근거를 설명한다.",
          "result": "해당 근거가 예외 상황에서 화면의 상태와 사용자의 다음 행동을 어떻게 분명하게 하는지 설명한다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 흐름을 설계한 구체적인 근거",
          "그 근거를 뒷받침하는 예외 상황과 화면 흐름의 연결",
          "설계한 흐름에서 화면 상태나 사용자의 다음 행동을 그렇게 정한 이유"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨을 때, 예외 상황의 화면 흐름을 그렇게 설계한 근거는 무엇이었나요?",
      "answerTip": "떠오르는 장면을 짚어 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제로 설계한 예외 상황의 화면 흐름을 들어 그 흐름을 택한 근거를 구체적으로 설명한다.",
            "제시한 근거가 예외 발생 시 화면 상태나 사용자의 다음 행동과 직접 연결되어 흐름을 명확하게 이해할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황의 화면 흐름을 설계한 근거를 제시하지만 사용자 편의 같은 일반적인 설명에 머문다.",
            "근거와 화면 흐름의 연결은 설명하지만 예외 발생 시 화면 상태나 다음 행동이 일부 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 포함했다는 사실이나 화면설계서의 분량만 말하고 설계 근거를 설명하지 못한다.",
            "화면 흐름의 판단 대신 Figma 기능이나 문서 표기 방식만 설명해 예외 상황 설계 능력을 확인할 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 그대로 수행하지 않고 확인하는 행동을 평가한다. 진통제 투약을 멈춘 판단의 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 근무 중 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "수술 전후 환자의 투약·처치를 담당했으며, 해당 처방은 투약 전에 확인이 필요한 상황이었다.",
          "action": "처방 용량에서 무엇을 의심했고 그것이 투약을 멈춰야 할 근거라고 판단한 이유를 설명한다.",
          "result": "담당의 확인 결과 입력 오류였다는 사실을 자신의 투약 중단 판단과 연결해 설명한다."
        },
        "expectedEvidence": [
          "진통제 투약을 멈추기로 판단한 근거",
          "처방 용량이 평소 용량의 두 배라는 차이를 확인 전 투약하면 안 되는 이유와 연결한 설명"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 투약을 멈춰야 한다고 판단한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 간결하게 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량과 처방 용량의 차이를 짚고, 그 차이가 처방 오류를 의심할 근거였음을 구체적으로 설명한다.",
            "처방의 정확성을 확인하지 않은 상태에서 투약할 때의 환자 위험을 투약 중단 판단과 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소보다 많은 용량이어서 투약을 멈췄다고 답하지만, 그 차이를 위험 신호로 본 설명은 제한적이다.",
            "의심스러운 처방은 확인해야 한다는 원칙을 제시하지만, 해당 처방에서 투약을 멈춘 근거는 일반적으로 설명한다."
          ]
        },
        "poor": {
          "criteria": [
            "담당의에게 확인했다는 조치나 입력 오류였다는 결과만 반복하고, 투약을 멈춘 판단 근거는 제시하지 않는다.",
            "처방이 의심스러워도 그대로 투약할 수 있다는 설명 등 확인 전 중단 행동과 어긋나는 근거를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 관련된 정보를 다음 근무자의 인수인계로 연결하는 판단을 평가한다. 진통제 투여 시각과 보행 보조 여부를 함께 전달해야 한다고 본 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 QI 활동에서 사고 보고서를 통해 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 확인했다.",
          "task": "낙상 고위험 환자 인수인계 체크리스트 개선에 참여해 진통제 투여 시각과 보행 보조 여부 항목을 추가했다.",
          "action": "진통제 투여 시각과 보행 보조 여부가 다음 근무자의 환자 상태 판단에 어떤 의미가 있어 함께 전달해야 한다고 보았는지 설명한다.",
          "result": "두 정보를 인수인계로 연결하는 판단이 교대 시 환자 상태와 보행 위험을 놓치지 않는 데 갖는 의미를 설명한다."
        },
        "expectedEvidence": [
          "진통제 투여 시각과 보행 보조 여부를 함께 인수인계해야 한다고 판단한 근거",
          "근무 교대 시간대의 낙상 양상과 두 정보의 전달 필요성을 연결한 설명"
        ]
      },
      "question": "푸른결종합병원 정형외과 병동 QI 활동에서 인수인계 체크리스트를 바꾸셨을 때, 진통제 투여 시각과 보행 보조 여부를 함께 전달해야 한다고 본 근거는 무엇이었나요?",
      "answerTip": "듣는 사람이 이해하기 쉽게 풀어 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 투여 시각과 보행 보조 여부가 환자의 상태와 보행 위험을 이해하는 데 필요한 이유를 구체적으로 설명한다.",
            "교대 시간대에 낙상이 몰린 관찰을 다음 근무자에게 두 정보를 함께 전달해야 한다는 판단과 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "두 정보를 전달해야 한다는 근거를 낙상 예방이나 환자 상태 파악과 연결하지만, 정보가 필요한 이유는 일반적으로 설명한다.",
            "교대 시 정보 누락을 줄여야 한다고 답하지만, 관찰된 낙상 양상과 두 정보의 관계는 일부만 설명한다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트에 추가한 항목이나 낙상 감소 수치만 반복하고, 함께 전달해야 한다고 본 근거는 제시하지 않는다.",
            "교육이나 물품 관리 등 다른 업무의 필요성만 설명하고, 환자 상태 정보를 인수인계로 연결하는 판단에는 답하지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P05",
  "interviews": [
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "분석 결론을 실제 캠페인 실행으로 옮길 수 있는지 확인한다. 게시물 유형별 비교 결과를 광고 소재 변경으로 연결한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 꽃집 인스타그램 광고 소액 집행 분석에서 월 10만 원씩 광고를 집행하며 게시물 유형별 클릭과 문의 DM 수를 비교했다.",
          "task": "가격 표기형의 문의가 가장 많아 광고 소재를 그쪽으로 바꿨다.",
          "action": "비교 결과 중 무엇을 근거로 가격 표기형을 실제 광고 소재에 반영하기로 판단했는지 설명한다.",
          "result": "그 판단을 뒷받침하는 소재 변경 전후의 문의 반응을 설명한다."
        },
        "expectedEvidence": [
          "가격 표기형으로 광고 소재를 바꾸기로 판단한 구체적인 근거",
          "그 판단을 뒷받침한 게시물 유형별 클릭 또는 문의 DM 비교 내용",
          "소재 변경 전후 문의 반응과 판단 근거의 연결"
        ]
      },
      "question": "동네 꽃집 인스타그램 광고에서 가격 표기형으로 소재를 바꾸셨을 때, 비교 결과를 실제 광고에 반영하기로 판단한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 간결하게 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "게시물 유형별 반응 차이를 근거로 가격 표기형을 실제 광고 소재로 선택한 판단을 구체적으로 설명한다.",
            "제시한 근거가 분석 결론과 소재 변경 사이를 직접 연결하며 단순한 취향이나 추측에 머물지 않는다."
          ]
        },
        "acceptable": {
          "criteria": [
            "가격 표기형의 반응이 좋아 소재를 바꿨다고 답하지만 비교 내용이 포괄적이다.",
            "분석 결과를 실제 광고에 반영한 판단은 드러나지만 그 선택을 뒷받침하는 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "소재를 바꿨다는 사실만 반복하고 변경을 결정한 근거를 설명하지 못한다.",
            "개인적인 디자인 선호나 일반적인 광고 지식만 말해 비교 결과와 실행의 연결이 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "캠페인 성과를 지표로 해석해 효과가 있었던 변경 내용을 보고할 수 있는지 확인한다. 보고서 형식이 아니라 사장님께 실제로 전달한 성과 설명에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 꽃집 인스타그램 광고에서 가격 표기형으로 소재를 바꾼 뒤 주간 문의 DM이 2~3건에서 6~7건으로 늘어났다.",
